#include "gateway_public_page.h"

const char GATEWAY_PUBLIC_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Tổng quan kho</title><link rel='stylesheet' href='/ui.css'><style>.public-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.warehouse-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.warehouse-tile{min-height:135px;padding:15px;border:1px solid var(--line);border-radius:15px;background:var(--glass)}.warehouse-tile .group{color:#a5b4fc;font-size:10px;font-weight:850;letter-spacing:.1em}.warehouse-tile .code{display:block;margin-top:6px;font-size:17px}.warehouse-tile .state{display:block;margin-top:18px;font-size:15px;font-weight:850}.warehouse-tile .meta{display:flex;align-items:center;gap:7px;margin-top:7px;color:var(--muted);font-size:11px}.warehouse-tile.EMPTY{border-color:rgba(52,211,153,.4);background:linear-gradient(145deg,rgba(20,53,48,.85),var(--glass))}.warehouse-tile.EMPTY .state{color:#86efac}.warehouse-tile.OCCUPIED{border-color:rgba(251,191,36,.48);background:linear-gradient(145deg,rgba(64,47,20,.8),var(--glass))}.warehouse-tile.OCCUPIED .state{color:#fde68a}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.summary div{padding:9px 11px;border:1px solid var(--line2);border-radius:9px;background:var(--glass2)}.summary small{display:block;color:var(--muted);font-size:10px}.summary b{display:block;margin-top:3px}@media(max-width:760px){.warehouse-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.summary{grid-template-columns:repeat(3,1fr)}}@media(max-width:390px){.warehouse-grid,.summary{grid-template-columns:1fr}}</style></head><body data-page='overview'><div class='shell'><header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Tổng quan kho</h1><p>Giám sát trạng thái theo thời gian thực</p></div></div><div class='public-actions' data-public-auth><a class='btn primary' href='/login'>Đăng nhập</a></div></header><nav class='nav'><a class='active' href='/'>TỔNG QUAN</a></nav><section id='summary' class='toolbar summary'><div><small>Profile</small><b id='profile'>--</b></div><div><small>Online</small><b id='online'>0</b></div><div><small>Không có hàng</small><b id='empty'>0</b></div><div><small>Có hàng</small><b id='occupied'>0</b></div><div><small>Chưa xác định</small><b id='unknown'>0</b></div></section><div class='header-status' style='justify-content:flex-start;margin-bottom:14px'><div class='status-chip identity'><i></i><small>Gateway</small><b id='gateway'>--</b></div><div class='status-chip' id='networkChip'><i></i><small>Mạng</small><b id='network'>--</b></div><div class='status-chip' id='mqttChip'><i></i><small>MQTT</small><b id='mqtt'>--</b></div><div class='status-chip' id='canChip'><i></i><small>CAN</small><b id='can'>--</b></div></div><main id='grid' class='warehouse-grid'></main></div><script src='/ui.js'></script><script>const $=x=>document.getElementById(x),esc=x=>String(x||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])),label=s=>s==='EMPTY'?'KHÔNG CÓ HÀNG':s==='OCCUPIED'?'CÓ HÀNG':'CHƯA XÁC ĐỊNH';async function load(){try{const d=await(await fetch('/api/public/status',{cache:'no-store'})).json();['gateway','profile','online','empty','occupied','unknown'].forEach(k=>$(k).textContent=d[k]);$('network').textContent=d.network.name;$('mqtt').textContent=d.mqtt?'Đã kết nối':'Chưa kết nối';$('can').textContent=d.can;$('networkChip').classList.toggle('ok',d.network.connected);$('mqttChip').classList.toggle('ok',d.mqtt);$('canChip').className='status-chip '+(d.can==='ACTIVE'?'ok':'bad');$('grid').innerHTML=d.positions.map(p=>`<article class='warehouse-tile ${p.state}'><span class='group'>GROUP ${p.group_id}</span><strong class='code'>${esc(p.warehouse_code||'Chưa cấu hình')}</strong><span class='state'>${label(p.state)}</span><span class='meta'><i class='dot ${p.sensor_online?'ok':'bad'}'></i>Laser ${p.laser_id||'--'} · ${p.sensor_online?'ONLINE':'OFFLINE'}</span></article>`).join('')}catch(e){}setTimeout(load,1000)}load()</script></body></html>";
